import { useFonts } from 'expo-font';

// Subset copies generated by scripts/subset-game-fonts.mjs. The keys are the
// family names used by --font-* in global.css, identical on every platform.
const gameFonts = {
  DelaGothicOne_400Regular: require('../../assets/fonts/DelaGothicOne_400Regular.ttf'),
  ZenKakuGothicNew_500Medium: require('../../assets/fonts/ZenKakuGothicNew_500Medium.ttf'),
  ZenKakuGothicNew_700Bold: require('../../assets/fonts/ZenKakuGothicNew_700Bold.ttf'),
  ZenMaruGothic_700Bold: require('../../assets/fonts/ZenMaruGothic_700Bold.ttf'),
};

/** True once the game fonts are usable or failed; text then falls back to system fonts. */
export function useGameFonts() {
  const [loaded, error] = useFonts(gameFonts);
  return loaded || error !== null;
}
